<template><div class="analytics"><div class="head"><div><h2>运营分析</h2><p>统计卡片下钻到业务明细与处理效率</p></div><el-radio-group v-model="type"><el-radio-button v-for="(v,k) in labels" :key="k" :value="k">{{v}}</el-radio-button></el-radio-group></div>
<el-card v-if="type==='chat'"><template #header>近30天聊天使用统计</template><el-table :data="data.chat||[]"><el-table-column prop="day" label="日期"/><el-table-column prop="total" label="聊天次数"/><el-table-column prop="users" label="使用人数"/><el-table-column prop="fallback" label="兜底次数"/></el-table></el-card>
<el-card v-if="type==='reminder'"><template #header>提醒完成与漏服分析</template><div class="metric-grid"><div v-for="x in data.reminder||[]" :key="x.action"><b>{{actionText[x.action]||x.action}}</b><strong>{{x.count}}</strong></div></div><el-button type="primary" @click="$router.push('/admin/users')">查看相关用户</el-button></el-card>
<el-card v-if="type==='warning'"><template #header>健康预警类型与处理率</template><el-table :data="data.warning||[]"><el-table-column prop="warning_type" label="预警类型"/><el-table-column prop="total" label="总数"/><el-table-column prop="handled" label="已处理"/><el-table-column label="处理率"><template #default="{row}">{{rate(row.handled,row.total)}}%</template></el-table-column></el-table></el-card>
<el-card v-if="type==='emergency'"><template #header>紧急求助响应效率</template><div class="metric-grid"><div><b>求助总数</b><strong>{{emergency.total||0}}</strong></div><div><b>平均确认</b><strong>{{duration(emergency.avg_ack_seconds)}}</strong></div><div><b>平均进入处理</b><strong>{{duration(emergency.avg_process_seconds)}}</strong></div><div><b>平均完成</b><strong>{{duration(emergency.avg_complete_seconds)}}</strong></div></div><el-button type="danger" @click="$router.push('/admin/emergency')">进入事件处理</el-button></el-card>
<el-card v-if="type==='binding'"><template #header>家属绑定状态</template><div class="metric-grid"><div v-for="x in data.binding||[]" :key="x.status"><b>{{bindingText[x.status]||x.status}}</b><strong>{{x.count}}</strong></div></div></el-card></div></template>
<script setup>import{computed,ref,onMounted}from'vue';import{useRoute}from'vue-router';import{adminApi}from'@/api/index';const route=useRoute(),type=ref(route.query.type||'chat'),data=ref({});const labels={chat:'聊天',reminder:'提醒',warning:'健康预警',emergency:'求助',binding:'家属绑定'},actionText={COMPLETED:'已完成',MISSED:'漏服/未确认',SKIPPED:'已跳过',SNOOZED:'稍后提醒'},bindingText={0:'已解除',1:'活跃绑定',2:'待审批',3:'已拒绝'};const emergency=computed(()=>data.value.emergency?.[0]||{});const rate=(a,b)=>b?Math.round(Number(a||0)*100/Number(b)):0;const duration=s=>s==null?'暂无':Number(s)<60?`${Math.round(s)}秒`:`${Math.round(s/60)}分钟`;onMounted(async()=>data.value=(await adminApi.analytics()).data||{})</script>
<style scoped>.analytics{display:grid;gap:18px}.head{display:flex;justify-content:space-between;align-items:center}.head h2{margin:0}.head p{color:#64748b}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:16px;margin-bottom:22px}.metric-grid div{background:#f8fafc;border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:10px}.metric-grid b{color:#64748b}.metric-grid strong{font-size:28px;color:#1e3a5f}</style>
